``` java
import org.junit.platform.engine.EngineDiscoveryRequest;
import org.junit.platform.engine.EngineExecutionListener;
import org.junit.platform.engine.ExecutionRequest;
import org.junit.platform.engine.TestDescriptor;
import org.junit.platform.engine.TestEngine;
import org.junit.platform.engine.TestExecutionResult;
import org.junit.platform.engine.UniqueId;
import org.junit.platform.engine.support.descriptor.AbstractTestDescriptor;
import org.junit.platform.engine.support.descriptor.EngineDescriptor;
import org.junit.platform.runner.JUnitPlatform;
import org.junit.runner.RunWith;

@RunWith(JUnitPlatform.class)
public class DemoTestEngine implements TestEngine {

    private UniqueId rootUid;

    @Override
    public String getId() {
        return "demo";
    }

    @Override
    public TestDescriptor discover(EngineDiscoveryRequest discoveryRequest, UniqueId uniqueId) {
        EngineDescriptor engineDescriptor = new EngineDescriptor(uniqueId, "demo");
        RootTestDescriptor root = new RootTestDescriptor(uniqueId.append("root", "0"), "root #0");
        engineDescriptor.addChild(root);
        this.rootUid = root.getUniqueId();
        return engineDescriptor;
    }

    @Override
    public void execute(ExecutionRequest request) {
        EngineExecutionListener engineExecutionListener = request.getEngineExecutionListener();
        TestDescriptor engineDescriptor = request.getRootTestDescriptor();
        TestDescriptor root = engineDescriptor.findByUniqueId(this.rootUid).get();

        TestDescriptor container = new ContainerTestDescriptor(this.rootUid.append("container", "1"), "container #1");
        root.addChild(container);

        engineExecutionListener.dynamicTestRegistered(container);
        engineExecutionListener.executionStarted(container);
        engineExecutionListener.executionFinished(container, TestExecutionResult.successful());

        UniqueId containerUid = container.getUniqueId();

        TestDescriptor dynamicTest1 = new TestTestDescriptor(containerUid.append("test", "1"), "dynamic test #1");
        container.addChild(dynamicTest1);
        engineExecutionListener.dynamicTestRegistered(dynamicTest1);
        engineExecutionListener.executionStarted(dynamicTest1);
        engineExecutionListener.executionFinished(dynamicTest1, TestExecutionResult.successful());

        TestDescriptor dynamicTest2 = new TestTestDescriptor(containerUid.append("test", "2"), "dynamic test #2");
        container.addChild(dynamicTest2);
        engineExecutionListener.dynamicTestRegistered(dynamicTest2);
        engineExecutionListener.executionStarted(dynamicTest2);
        engineExecutionListener.executionFinished(dynamicTest2, TestExecutionResult.successful());
    }

    static class RootTestDescriptor extends AbstractTestDescriptor {

        RootTestDescriptor(UniqueId uniqueId, String displayName) {
            super(uniqueId, displayName);
        }

        @Override
        public boolean isContainer() {
            return true;
        }

        @Override
        public boolean isTest() {
            return false;
        }

        @Override
        public boolean hasTests() {
            return true;
        }
    }

    static class ContainerTestDescriptor extends AbstractTestDescriptor {

        ContainerTestDescriptor(UniqueId uniqueId, String displayName) {
            super(uniqueId, displayName);
        }

        @Override
        public boolean isContainer() {
            return true;
        }

        @Override
        public boolean isTest() {
            return false;
        }
    }

    static class TestTestDescriptor extends AbstractTestDescriptor {

        TestTestDescriptor(UniqueId uniqueId, String displayName) {
            super(uniqueId, displayName);
        }

        @Override
        public boolean isContainer() {
            return false;
        }

        @Override
        public boolean isTest() {
            return true;
        }
    }

}
```

